/**
 * A 128 × 64 WebM (VP8, 10 fps, 2 s) for animated map tests, made with ffmpeg:
 * the first second blue on the left half and red on the right, the next green and yellow.
 *
 * ffmpeg -f lavfi -i color=c=blue:s=64x64:r=10:d=1 -f lavfi -i color=c=red:s=64x64:r=10:d=1 \
 *   -f lavfi -i color=c=0x00ff00:s=64x64:r=10:d=1 -f lavfi -i color=c=yellow:s=64x64:r=10:d=1 \
 *   -filter_complex "[0][1]hstack[a];[2][3]hstack[b];[a][b]concat=n=2:v=1:a=0,format=yuv420p[v]" \
 *   -map "[v]" -c:v libvpx -b:v 0 -crf 4 -g 10 -auto-alt-ref 0 -an fixture.webm
 */
const VIDEO_MAP_WEBM_BASE64 = '';

export const VIDEO_MAP_SIZE = { width: 128, height: 64 } as const;

/** The fixture's bytes, a new buffer each call. */
export function videoMapWebm(): ArrayBuffer {
  const binary = atob(VIDEO_MAP_WEBM_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}
